loadPEMCertificate(file, certType) {
  dump("Loading certificate from " + file.path + "\n");
  const certDB = Cc["@mozilla.org/security/x509certdb;1"].getService(
    Ci.nsIX509CertDB
  );
  certDB.importCertsFromFile(file, certType);
},

loadCertificateAndKey(file, pw) {
  dump("Loading key from " + file.path + " with password: [" + pw + "]\n");
  const certDB = Cc["@mozilla.org/security/x509certdb;1"].getService(
    Ci.nsIX509CertDB
  );
  const importResult = certDB.importPKCS12File(file, pw);
  if (importResult != 0) {
    throw new Error("importPKCS12File failed, error code: " + importResult);
  }
},

/**
 * Delete certificates from the database, e.g. to clean up after a test.
 *
 * @param {string[]} commonNames - Every certificate whose commonName is in
 *   this list is deleted.
 */
async removeCertificates(commonNames) {
  const certDB = Cc["@mozilla.org/security/x509certdb;1"].getService(
    Ci.nsIX509CertDB
  );
  for (const cert of await certDB.getCerts()) {
    if (commonNames.includes(cert.commonName)) {
      certDB.deleteCertificate(cert);
    }
  }
},
